<?php use Namira\Security; $uploadBatch=min(10,max(1,intdiv((int)ini_get('max_file_uploads'),2))); ?>
<section class="panel"><h2>بارگذاری اصل تصاویر</h2><p>ابتدا شهید ثبت شود. نام فایل مانند <b dir="ltr">001254-1.jpg</b> باشد. حداکثر <?= fa($uploadBatch) ?> فایل در هر نوبت؛ فایل‌های اصلی تغییر نمی‌کنند. تصاویر پس از بارگذاری مستقیماً در آرشیو عمومی منتشر می‌شوند.</p><form method="post" enctype="multipart/form-data" action="<?= e(url('admin',['tab'=>'images'])) ?>" data-upload-form data-upload-preview="true" data-max-files="<?= $uploadBatch ?>"><?= Security::field() ?><input type="hidden" name="action" value="images"><div class="fields"><?php foreach(['title'=>'عنوان (اختیاری)','designer'=>'طراح','license_text'=>'شرایط استفاده'] as $k=>$label): ?><div class="field"><label for="<?= $k ?>"><?= $label ?></label><input id="<?= $k ?>" name="<?= $k ?>"></div><?php endforeach ?><div class="field"><label for="kind">نوع</label><select name="media_type_id" id="kind"><?php foreach(Namira\Db::query($db,"SELECT id,title FROM protocol_terms WHERE taxonomy='media_type' AND active=1 ORDER BY sort_order,id")->fetchAll() as $type): ?><option value="<?= $type['id'] ?>"><?= e($type['title']) ?></option><?php endforeach ?></select></div><div class="field full"><label for="images">فایل‌ها</label><input id="images" type="file" name="images[]" multiple required accept=".jpeg,.jpg,.png,.webp,image/jpeg,image/png,image/webp" aria-describedby="image-formats"></div></div><p class="hint" id="image-formats">فرمت‌های مجاز: JPEG، JPG، PNG و WebP. حداکثر <?= fa($uploadBatch) ?> فایل در هر نوبت. اصل فایل بدون تغییر ارسال می‌شود؛ مرورگر یک پیش‌نمایش سبک جدا می‌سازد. سپس درصد و حجم باقی‌مانده نمایش داده می‌شود.</p><?php view('upload-status'); ?><button class="primary">بارگذاری و انتشار</button></form></section>